const minute=t=>{const [h,m]=t.split(':').map(Number);return h*60+m+(h<6?1440:0)};
fetch('data.json').then(r=>r.json()).then(acts=>{
 document.querySelector('#timeline-list').innerHTML=acts.map((a,i)=>{
 const next=acts[i+1],gap=next?minute(next.start)-minute(a.end):null;
 return `<a class="stop" href="#${a.key}"><span class="stop-time">${a.start}—${a.end}${minute(a.start)>=1440?'<small>SUNDAY 25 OCT</small>':''}</span><span class="stop-index">${String(i+1).padStart(2,'0')}</span><span><span class="stop-name">${a.name}</span><span class="stop-venue">${a.venue} · ${minute(a.end)-minute(a.start)} min</span></span><span class="stop-arrow">↗</span></a>${next?`<div class="gap ${gap===0?'tight':''}">${gap===0?'No transfer time · leave early / arrive late':gap+' min gap · '+(a.venue===next.venue?'stay at '+a.venue:a.venue+' → '+next.venue)}</div>`:''}`;
 }).join('');
 const imageSources={kelly:['Release artwork · Apple Music','https://music.apple.com/us/artist/kelly-no-brakes/1876292105'],really:['Press image · Prescription PR','https://www.prescriptionmusicpruk.com/press-releases/really-good-time-share-new-single-bob-dylan-was-on-pawn-stars-in-2010'],mleko:['Artist image · Heist or Hit','https://www.heistorhit.com/artists/mleko/'],snayx:['Artist image · The Deaf Institute','https://www.thedeafinstitute.co.uk/event/snayx/'],plantoid:['Artist image · TJPL News','https://www.tjplnews.com/post/plantoid-brighton-psychedelic-rock-revolution'],iguana:['Artist image · MP3s & NPCs','https://mp3sandnpcs.com/home/dutch-garage-rock-band-iguana-death-cult-announce-new-album-echo-palace-share-new-song'],dove:['Artist portrait · TIDAL','https://tidal.com/artist/38691383'],mike:['Video still · Universal Music Canada','https://www.universalmusic.ca/2026/10/07/mike-d-secrets-pts-i-ii-video-out-now/'],painkiller:['Artist image · Left of the Dial','https://leftofthedial.nl/acts/painkiller/'],alien:['Artist image · Bandcamp','https://alienchicks.bandcamp.com/'],cowboy:['Photo: Lucy Craig · Prescription PR','https://prescriptionmusicpr.squarespace.com/press-releases/cowboy-hunters-share-highly-requested-single-punched-in-the-head']};
 document.querySelector('#artist-list').innerHTML=acts.map((a,i)=>`<article class="artist" id="${a.key}"><figure class="artist-image"><img loading="lazy" src="assets/${a.key}.jpg" alt="${a.key==='kelly'?'Kelly No Brakes release artwork':a.name}"><figcaption><a href="${imageSources[a.key][1]}" target="_blank" rel="noopener">${imageSources[a.key][0]} ↗</a></figcaption></figure><div><p class="artist-number">${String(i+1).padStart(2,'0')} / YOUR SATURDAY</p><h3>${a.name}</h3><p class="artist-tag">${a.tag}</p><div class="artist-meta">${a.start}—${a.end} ${minute(a.start)>=1440?'· Sunday ': '· '}${a.venue} / ${a.street}</div><p class="artist-bio">${a.bio}</p><p style="font-size:11px;color:var(--muted)">A listening starting point: <b>${a.listen}</b></p><div class="links"><a href="https://open.spotify.com/search/${encodeURIComponent(a.name==='Painkiller'?'Painkiller Tom Rees':a.name)}" target="_blank" rel="noopener">Find on Spotify ↗</a><a href="${a.source}" target="_blank" rel="noopener">Profile source ↗</a><a href="https://www.google.com/maps/search/?api=1&query=${encodeURIComponent(a.venue+' Brighton '+a.street)}" target="_blank" rel="noopener">Venue map ↗</a></div></div></article>`).join('');
}).catch(()=>{document.querySelector('#timeline-list').textContent='The schedule could not load. Please refresh the page.'});
